INSERT INTO "supporting_documents" ("id","title","source_type","mime_type","r2_object_key","r2_url","external_url","description","tags_json","metadata","is_active","is_fact_record","revision_number","revision_of_id","replaced_by_id","ai_rationale","datetime_created","datetime_updated") VALUES('916ae061-d6eb-4ea1-a76f-611580d1e376','1971 original blueprint','pdf','application/pdf','supporting-documents/2026/05/adc454cf-873c-48dc-8c2e-c9e5d6bba486-1971_Blueprints_-_joists.pdf','/api/artifacts/supporting-documents/2026/05/adc454cf-873c-48dc-8c2e-c9e5d6bba486-1971_Blueprints_-_joists.pdf',NULL,'Reflects as is built and will provide information on the structural wall layout and the envy structure around the footings, etc., on the structural wall in the lower level and on the upstairs kitchen wall will highlight the structural of that wall as well, which is as far as we know not structural',NULL,NULL,1,1,1,NULL,NULL,'The 1971 original blueprint is relevant to the lower-bedroom-1 as it provides information on the structural wall layout in the lower level, which includes this bedroom. This document will help identify the structural components of the walls in this room, informing any potential remodel or renovation plans.',1779057921,1781882434);
INSERT INTO "supporting_documents" ("id","title","source_type","mime_type","r2_object_key","r2_url","external_url","description","tags_json","metadata","is_active","is_fact_record","revision_number","revision_of_id","replaced_by_id","ai_rationale","datetime_created","datetime_updated") VALUES('12c3bada-460c-4c6d-aede-2f2559b02dc2','Subzero Fridge Product Specification','pdf','application/pdf','supporting-documents/2026/06/f670c00a-78d4-4ccd-ad52-56d552fe0b3d-product_specification.pdf','/api/artifacts/supporting-documents/2026/06/f670c00a-78d4-4ccd-ad52-56d552fe0b3d-product_specification.pdf',NULL,replace(replace('Provides the specs for kitchen layout planning and cabinet manufacturing. \r\n\r\nNOTE: Fridge is right opening.','\r',char(13)),'\n',char(10)),NULL,NULL,1,1,1,NULL,NULL,'This document is relevant to the Kitchen as it provides essential specifications for the Subzero fridge, which will inform kitchen layout planning and cabinet manufacturing to ensure a proper fit. The fact that the fridge has a right opening is particularly important for designing the surrounding kitchen space.',1781618785,1781882411);
INSERT INTO "supporting_documents" ("id","title","source_type","mime_type","r2_object_key","r2_url","external_url","description","tags_json","metadata","is_active","is_fact_record","revision_number","revision_of_id","replaced_by_id","ai_rationale","datetime_created","datetime_updated") VALUES('cfe496de-77ec-4113-bc7e-026c671a0a42','Subzero Fridge Product Specification','pdf','application/pdf','supporting-documents/2026/06/82d735e0-e625-429e-9461-b4be6bd0e41f-designer-series-design-guide.pdf','/api/artifacts/supporting-documents/2026/06/82d735e0-e625-429e-9461-b4be6bd0e41f-designer-series-design-guide.pdf',NULL,replace(replace('Provides the specs for kitchen layout planning and cabinet manufacturing. \r\n\r\nNOTE: Fridge is right opening.','\r',char(13)),'\n',char(10)),NULL,NULL,1,1,1,NULL,NULL,'The Subzero Fridge Product Specification document is relevant to the Kitchen as it provides crucial details for layout planning and cabinet manufacturing, ensuring a seamless integration of the fridge into the kitchen design. This document''s specifications, including the right-opening feature, will inform decisions on kitchen layout and cabinetry to accommodate the Subzero fridge.',1781618786,1781882411);
INSERT INTO "supporting_documents" ("id","title","source_type","mime_type","r2_object_key","r2_url","external_url","description","tags_json","metadata","is_active","is_fact_record","revision_number","revision_of_id","replaced_by_id","ai_rationale","datetime_created","datetime_updated") VALUES('cf0f0497-36c9-4d44-91cf-6619cf4b454c','Thermadoor Hood','pdf','application/pdf','supporting-documents/2026/06/955dea9c-569e-4510-bdfe-b92d74b4e341-9001030275_A.pdf','/api/artifacts/supporting-documents/2026/06/955dea9c-569e-4510-bdfe-b92d74b4e341-9001030275_A.pdf',NULL,'Specs for the the Thermadoor hood so it can be enclosed with drywall or other materials.',NULL,NULL,1,1,1,NULL,NULL,'The Thermadoor Hood document is relevant to the Kitchen as it provides specifications for installing and enclosing the range hood with drywall or other materials. This information will be useful for contractors or DIY homeowners working on the kitchen remodel, particularly when it comes to finishing the area around the range hood.',1781618874,1781882411);
INSERT INTO "supporting_documents" ("id","title","source_type","mime_type","r2_object_key","r2_url","external_url","description","tags_json","metadata","is_active","is_fact_record","revision_number","revision_of_id","replaced_by_id","ai_rationale","datetime_created","datetime_updated") VALUES('4494c3bc-44dd-4073-a587-e638ddc23ca0','Thermadoor Hood','pdf','application/pdf','supporting-documents/2026/06/bbc74014-453d-4ea0-b483-c9e1aaa09dbd-9000903087_A.pdf','/api/artifacts/supporting-documents/2026/06/bbc74014-453d-4ea0-b483-c9e1aaa09dbd-9000903087_A.pdf',NULL,'Specs for the the Thermadoor hood so it can be enclosed with drywall or other materials.',NULL,NULL,1,1,1,NULL,NULL,'The Thermadoor Hood document is relevant to the Kitchen as it provides specifications for enclosing the hood with drywall or other materials, which is a crucial step in the kitchen remodeling process. This document will help ensure a proper and safe installation of the hood in the kitchen.',1781618876,1781882411);
