INSERT INTO "dialer_prospects" ("id","rank","first_name","last_name","full_name","firm","roles","permit_count","avg_cost","median_cost","scope_keywords","is_unbundled_candidate","collision_risk","phone","phone_source","email","email_source","website","contact_status","license_note","call_script","created_at","license_no","distinct_licenses","distinct_firms","distinct_zips","agent_zip","agent_address","agent_city","agent_state") VALUES('tony-lee-1',1,'Tony','Lee','Tony Lee','Hing Wah Design','architect / designer',120,232864,210000,'bath, full, kitchen, remodel, bathroom, rear',1,1,NULL,NULL,NULL,NULL,NULL,'needs_research',NULL,replace('Hi, is this Tony? My name''s Justin — I''m a homeowner doing a kitchen remodel here in San Francisco that involves opening a structural wall and correcting a plumbing defect in the main waste stack.\n\nI''ll be upfront about how I found you: I went through the SF DBI permit database, and your name came up on roughly 120 single-family kitchen & bath remodel permits over the last couple of years.\n\nYou don''t have much of a web presence, so the permit records were how I found you — which usually means you stay busy on word of mouth.\n\nMy situation: I already have my GC and a structural engineer lined up. The piece I''m missing is a clean, permit-ready drawing set — not full-service design.\n\nDo you take permit-only / unbundled work, and would you have capacity in the next few weeks? Happy to send the scope and the engineer''s prelim — what''s the best email for that?','\n',char(10)),'CURRENT_TIMESTAMP',NULL,0,6,1,'94124',NULL,NULL,NULL);
