INSERT INTO "dialer_prospects" ("id","rank","first_name","last_name","full_name","firm","roles","permit_count","avg_cost","median_cost","scope_keywords","is_unbundled_candidate","collision_risk","phone","phone_source","email","email_source","website","contact_status","license_note","call_script","created_at","license_no","distinct_licenses","distinct_firms","distinct_zips","agent_zip","agent_address","agent_city","agent_state") VALUES('damaris-rodas-90',90,'Damaris','Rodas','Damaris Rodas','Kloud B Studio Inc','pmt consultant/expediter',5,195625,61500,'like, remodel, changes, kitchen, layout, bath',0,1,NULL,NULL,NULL,NULL,NULL,'needs_research',NULL,replace('Hi, is this Damaris? My name''s Justin — I''m a homeowner doing a kitchen remodel here in San Francisco that involves opening a structural wall and correcting a plumbing defect in the main waste stack.\n\nI''ll be upfront about how I found you: I went through the SF DBI permit database, and your name came up on roughly 5 single-family kitchen & bath remodel permits over the last couple of years.\n\nI also saw you do permit expediting — someone who can walk the set through DBI is exactly what I''m after.\n\nMy situation: I already have my GC and a structural engineer lined up. The piece I''m missing is a clean, permit-ready drawing set — not full-service design.\n\nDo you take permit-only / unbundled work, and would you have capacity in the next few weeks? Happy to send the scope and the engineer''s prelim — what''s the best email for that?','\n',char(10)),'CURRENT_TIMESTAMP',NULL,0,2,0,NULL,NULL,NULL,NULL);
INSERT INTO "dialer_call_attempts" ("id","prospect_id","outcome","note","created_at") VALUES(1,'tony-lee-1','voicemail',NULL,'CURRENT_TIMESTAMP');
INSERT INTO "dialer_call_attempts" ("id","prospect_id","outcome","note","created_at") VALUES(2,'tony-lee-1','connected',NULL,'CURRENT_TIMESTAMP');
